-- Private: the official entrypoint executes this once on a new database only.
-- An existing database must retain its roles and secrets; do not rerun blindly.
\set ON_ERROR_STOP on
BEGIN;
CREATE ROLE simplestchat_migrate
  LOGIN NOSUPERUSER NOCREATEDB NOCREATEROLE NOREPLICATION NOBYPASSRLS
  CONNECTION LIMIT 5 PASSWORD '2222222222222222222222222222222222222222222222222222222222222222';
CREATE ROLE simplestchat_app
  LOGIN NOSUPERUSER NOCREATEDB NOCREATEROLE NOREPLICATION NOBYPASSRLS
  CONNECTION LIMIT 25 PASSWORD '3333333333333333333333333333333333333333333333333333333333333333';

REVOKE ALL ON DATABASE simplestchat FROM PUBLIC;
GRANT CONNECT ON DATABASE simplestchat
  TO simplestchat_migrate, simplestchat_app;
REVOKE ALL ON SCHEMA public FROM PUBLIC;
GRANT USAGE, CREATE ON SCHEMA public TO simplestchat_migrate;
GRANT USAGE ON SCHEMA public TO simplestchat_app;

-- Migration 011 can reuse this without granting database CREATE to its role.
CREATE EXTENSION pg_trgm WITH SCHEMA public;
-- Query statistics for the operator (the server is started with it preloaded).
CREATE EXTENSION pg_stat_statements WITH SCHEMA public;
COMMIT;

outputs.runtime-grants.sql:
-- Run as postgres after the packaged migration ledger has been verified.
-- Keep this allowlist explicit: the runtime must never edit _sqlx_migrations.
\set ON_ERROR_STOP on
BEGIN;
GRANT SELECT, INSERT, UPDATE
  ON public.users
  TO simplestchat_app;
GRANT SELECT, INSERT, UPDATE, DELETE
  ON public.webauthn_credentials
  TO simplestchat_app;
GRANT SELECT, INSERT, UPDATE, DELETE
  ON public.sessions, public.rooms, public.room_roles,
     public.room_states, public.room_reports, public.moderation_events,
     public.invites, public.chat_messages, public.chat_inbox, public.chat_read_cursors, public.chat_pins, public.push_subscriptions,
     public.contacts, public.saved_rooms, public.account_notification_preferences, public.conversation_notification_preferences, public.attachments
  TO simplestchat_app;
GRANT SELECT, INSERT
  ON public.push_keys
  TO simplestchat_app;
GRANT SELECT, INSERT, DELETE
  ON public.invite_redemptions, public.session_access_tokens
  TO simplestchat_app;
COMMIT;

